package com.clinica.backend.controller;
import com.clinica.backend.dto.*; import com.clinica.backend.service.ClinicService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/patients") public class PatientController{private final ClinicService clinic;public PatientController(ClinicService c){clinic=c;}@GetMapping("/public") public List<PublicPatientResponse> publicList(){return clinic.publicPatients();}@GetMapping("/exists/{cedula}") public Map<String,Boolean> exists(@PathVariable String cedula){return clinic.patientExists(cedula);}@GetMapping public List<PatientResponse> list(){return clinic.patients();}@PostMapping @ResponseStatus(HttpStatus.CREATED) public PatientResponse create(@Valid @RequestBody PatientRequest r){return clinic.createPatient(r);}}
